def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    marks=[(r,c,v) for r in range(h) for c in range(w) if (v:=g[r][c]) not in (2,8)]
    color=marks[0][2] if marks else 0
    # Replace marked cells by 4 and extend their color toward the grid's right edge.
    for r,c,v in marks:
        g[r][c]=4
        for j in range(c+1,w):
            if g[r][j] in (2,8): break
            g[r][j]=v
    # Paired boundary cells generate an inward horizontal line from the bar's inner edge.
    bars=[]
    for r in range(h):
        for c in range(w-1):
            if g[r][c]==g[r][c+1]==2: bars.append((r,c))
    for r,c in bars:
