def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # A horizontal pair projects a perpendicular line from its inward end:
    # top-edge pairs use the left member; bottom-edge pairs use the cell right of the pair.
    tracks=[]
    for r in range(h):
        for c in range(w-1):
            if grid[r][c]==grid[r][c+1]==2:
                if r==0:
                    tracks.append((c, 1, h))
                elif r==h-1 and c+2<w:
                    tracks.append((c+2, 0, h-1))
    # Draw boundary lines in marker color.
    markers=[(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (2,8)]
    color=markers[0][2] if markers else 5
    for c,start,stop in tracks:
        for r in range(start,stop):
            if g[r][c]==8: g[r][c]=color
    # Project each marker horizontally toward the nearest track. Source becomes 4.
    for r,c,v in markers:
        target=min((tc for tc,_,_ in tracks),key=lambda tc:abs(tc-c)) if tracks else (0 if c>w//2 else w-1)
        step=1 if target>c else -1
        cc=c+step
        while (cc<=target if step>0 else cc>=target):
            if g[r][cc]==8: g[r][cc]=v
            cc+=step
        g[r][c]=4
    return g

