def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    # Color 2 edge pairs establish the two vertical guide columns: the left
    # member of the top pair and the cell immediately right of the bottom pair.
    guides=[]
    for r in range(h):
        for c in range(w-1):
            if grid[r][c:c+2]==[2,2]:
                if r==0: guides.append(c)
                elif r==h-1 and c+2<w: guides.append(c+2)
    # Guide lines are in the singleton color.
    ink=next((grid[r][c] for r in range(h) for c in range(w) if grid[r][c] not in (2,8)),5)
    for c in guides:
        for r in range(h):
            if grid[r][c]==8: g[r][c]=ink
    # Each singleton emits a horizontal ray toward the other guide; marker -> 4.
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v not in (2,8):
                g[r][c]=4
                target=min(guides,key=lambda x:abs(x-c)) if guides else (w-1-c)
                d=1 if target>c else -1
                cc=c+d
                while 0<=cc<w and cc!=target+d:
                    if g[r][cc]==8: g[r][cc]=v
                    cc+=d
    return g
