def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # The paired endpoints mark the two long color-5 tracks, while each isolated
    # marker turns to 4 and projects its color toward the corresponding track.
    for r in range(h):
        for c in range(w-1):
            if grid[r][c:c+2]==[2,2]:
                if r==0:
                    for rr in range(1,h):
                        if g[rr][c]==8: g[rr][c]=5
                elif r==h-1 and c+2<w:
                    for rr in range(h-1):
                        if g[rr][c+2]==8: g[rr][c+2]=5
    for r in range(h):
        for c in range(w):
            if grid[r][c]==5:
                g[r][c]=4
                # Project toward the nearest guide column, stopping at the guide.
                guides=[x for x in range(w) if any(g[rr][x]==5 for rr in range(h))]
                if guides:
                    t=min(guides,key=lambda x:abs(x-c))
                    d=1 if t>c else -1
                    cc=c+d
                    while cc!=t+d:
                        if g[r][cc]==8: g[r][cc]=5
                        cc+=d
    return g
