def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Single colored marks become 4s; project toward a paired boundary when aligned.
    pairs=[]
    for r in range(h):
        for c in range(w-1):
            if grid[r][c]==grid[r][c+1]:
                pairs.append((r,c))
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v in (2,5) and v!=8 and not (v==2 and any(grid[r][x]==2 for x in range(w))):
                # task markers are isolated color distinct from background and paired boundary
                pass
    marks=[(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (2,8)]
    for r,c,v in marks:
        g[r][c]=4
        # Align to paired boundary in same column; project downward/upward to it.
        candidates=[pr for pr,pc in pairs if pc<=c<=pc+1 and (pr-r)*(1 if pr>r else -1)>0]
        if candidates:
            end=min(candidates,key=lambda pr:abs(pr-r))
            d=1 if end>r else -1
            for rr in range(r+d,end,d):
                if g[rr][c]==8: g[rr][c]=v
    return g
